class Box {
    int a, b, c;
public:
    Box() : a(1), b(1), c(1) {
        cout << "Default constructor: 1 x 1 x 1" << endl;
    }
    Box(int s) : a(s), b(s), c(s) {
        cout << "Cube constructor: " << s << " x " << s << " x " << s << endl;
    }
    Box(int l, int w) : a(l), b(w), c(1) {
        cout << "Box constructor: " << l << " x " << w << " x 1" << endl;
    }
    void volume() {
        cout << "Volume: " << a * b * c << endl;
    }
};

int main() {
    int k;
    cin >> k;
    if (k == 0) {
        Box b;
        b.volume();
    } else if (k == 1) {
        int s;
        cin >> s;
        Box b(s);
        b.volume();
    } else {
        int l, w;
        cin >> l >> w;
        Box b(l, w);
        b.volume();
    }
    return 0;
}

