#include <iostream>
using namespace std;

class Buffer {
    int size;
    int *data;
public:
    Buffer(int n) {
        size = n;
        data = new int[size];
        for (int i = 0; i < size; i++) {
            data[i] = i + 1;
        }
        cout << "Buffer created with " << size << " slots" << endl;
    }
    Buffer(const Buffer &other) {
        size = other.size;
        data = new int[size];
        for (int i = 0; i < size; i++) {
            data[i] = other.data[i];
        }
        cout << "Deep copy of " << size << " slots performed" << endl;
    }
    ~Buffer() {
        delete[] data;
        cout << "Buffer freed" << endl;
    }
    void set(int idx, int val) {
        data[idx] = val;
    }
    void print(const char *label) {
        cout << label << ":";
        for (int i = 0; i < size; i++) {
            cout << " " << data[i];
        }
        cout << endl;
    }
};

int main() {
    int n;
    cin >> n;
    Buffer a(n);
    Buffer b = a;
    a.print("Original");
    b.print("Copy");
    b.set(0, 100);
    b.print("Copy after edit");
    a.print("Original after edit");
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class IntStack {
    int *data;
    int cap;
    int top;
public:
    IntStack(int c) {
        cap = c;
        top = 0;
        data = new int[cap];
        cout << "Stack allocated with capacity " << cap << endl;
    }
    ~IntStack() {
        delete[] data;
        cout << "Stack memory released" << endl;
    }
    void push(int v) {
        if (top == cap) {
            cout << "Stack overflow" << endl;
            return;
        }
        data[top] = v;
        top++;
        cout << "Pushed " << v << endl;
    }
    void pop() {
        if (top == 0) {
            cout << "Stack underflow" << endl;
            return;
        }
        top--;
        cout << "Popped " << data[top] << endl;
    }
};

int main() {
    int cap, k;
    cin >> cap >> k;
    IntStack s(cap);
    for (int i = 0; i < k; i++) {
        string op;
        cin >> op;
        if (op == "push") {
            int v;
            cin >> v;
            s.push(v);
        } else {
            s.pop();
        }
    }
    return 0;
}

